## 3. Result-Generation Logic (form data → recommendation)

The actual recommendation logic is the inline `evaluate()` function (and its supporting types/defaults) defined in the Compass page. The generic `pdfExport.ts` utility (used to render the result/appeal PDF) follows it.

Source: `client/src/pages/IVFCompass.tsx`

```tsx
const STEPS = ["Infertility History", "Ovarian Reserve", "Male Factor", "Prior Treatment", "Assessment"];

type InfertilityDuration = "lt6" | "6to12" | "gt12" | "gt24";
type OvarianReserve = "normal" | "diminished" | "poor" | "premature_failure";
type MaleFactor = "none" | "mild" | "moderate" | "severe" | "azoospermia";

interface IVFInputs {
  femaleAge: number;
  infertilityDuration: InfertilityDuration;
  ovarianReserve: OvarianReserve;
  amhLevel: number;
  afcCount: number;
  maleFactor: MaleFactor;
  tubalFactor: boolean;
  uterineFactor: boolean;
  endometriosis: boolean;
  unexplained: boolean;
  priorIUIAttempts: number;
  priorIVFAttempts: number;
  priorIVFSuccess: boolean;
  stateMandate: boolean;
  oncologyIndication: boolean;
}

const defaultInputs: IVFInputs = {
  femaleAge: 0, infertilityDuration: "gt12", ovarianReserve: "normal",
  amhLevel: 0, afcCount: 0, maleFactor: "none", tubalFactor: false,
  uterineFactor: false, endometriosis: false, unexplained: false,
  priorIUIAttempts: 0, priorIVFAttempts: 0, priorIVFSuccess: false,
  stateMandate: false, oncologyIndication: false,
};

function evaluate(inputs: IVFInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Practice Committee of the American Society for Reproductive Medicine. Definitions of infertility and recurrent pregnancy loss. Fertil Steril. 2020;113(3):533-535.",
    "Practice Committee of the ASRM. Guidance on the limits to the number of embryos to transfer. Fertil Steril. 2021;116(3):651-654.",
    "Zegers-Hochschild F, et al. International Committee for Monitoring Assisted Reproductive Technology (ICMART) and the World Health Organization (WHO) revised glossary of ART terminology. Fertil Steril. 2009;92(5):1520-1524.",
    "CDC ART Success Rates. National Summary Report. Centers for Disease Control and Prevention. 2022.",
    "ASRM Practice Committee. Optimizing natural fertility: a committee opinion. Fertil Steril. 2022;117(1):53-63.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "A";
  let successRate = "";

  // Age-based success rates (CDC 2022 data)
  if (inputs.femaleAge < 35) successRate = "~40–50% live birth per cycle";
  else if (inputs.femaleAge < 38) successRate = "~30–40% live birth per cycle";
  else if (inputs.femaleAge < 41) successRate = "~20–30% live birth per cycle";
  else if (inputs.femaleAge < 43) successRate = "~10–15% live birth per cycle";
  else successRate = "~3–5% live birth per cycle (donor egg discussion recommended)";

  // Determine IVF indication
  const hasIndication = inputs.tubalFactor || inputs.uterineFactor ||
    inputs.maleFactor === "severe" || inputs.maleFactor === "azoospermia" ||
    inputs.ovarianReserve === "diminished" || inputs.ovarianReserve === "poor" ||
    inputs.ovarianReserve === "premature_failure" ||
    inputs.oncologyIndication ||
    (inputs.priorIUIAttempts >= 3 && inputs.infertilityDuration === "gt12") ||
    (inputs.unexplained && inputs.priorIUIAttempts >= 3) ||
    inputs.endometriosis;

  if (inputs.oncologyIndication) {
    recommendation = "indicated";
    procedure = "IVF with embryo cryopreservation (oncofertility)";
    cor = "I"; loe = "A";
    rationale.push("Oncofertility: IVF with embryo cryopreservation is the most established method of fertility preservation before gonadotoxic therapy (ASRM/ASCO).");
    warnings.push("Time-sensitive: coordinate with oncology team to begin IVF stimulation before chemotherapy/radiation.");
  } else if (inputs.tubalFactor) {
    recommendation = "indicated";
    procedure = "IVF (tubal factor infertility — first-line)";
    cor = "I"; loe = "A";
    rationale.push("Bilateral tubal occlusion or severe tubal damage: IVF is first-line treatment per ASRM guidelines.");
  } else if (inputs.maleFactor === "severe" || inputs.maleFactor === "azoospermia") {
    recommendation = "indicated";
    procedure = "IVF with ICSI (severe male factor)";
    cor = "I"; loe = "A";
    rationale.push("Severe male factor or azoospermia: IVF/ICSI is required — natural conception or IUI is not feasible.");
  } else if (hasIndication) {
    recommendation = "indicated";
    procedure = "IVF";
    cor = "I"; loe = "A";
    rationale.push("Multiple infertility factors identified meeting ASRM criteria for IVF.");
  } else if (inputs.infertilityDuration === "gt12" && inputs.priorIUIAttempts < 3) {
    recommendation = "consider";
    procedure = "IUI trials before IVF (3 cycles recommended)";
    cor = "IIa"; loe = "B";
    rationale.push("ASRM recommends 3–6 IUI cycles before proceeding to IVF in unexplained or mild infertility without absolute IVF indications.");
  } else {
    recommendation = "not_indicated";
    procedure = "Continue evaluation / IUI trials";
    rationale.push("IVF criteria not yet met: complete infertility workup and consider IUI trials first.");
  }

  if (inputs.femaleAge >= 38) {
    warnings.push(`Age ${inputs.femaleAge}: ASRM recommends expedited evaluation and treatment. Do not delay IVF unnecessarily.`);
  }
  if (inputs.femaleAge >= 40 && inputs.ovarianReserve === "poor") {
    warnings.push("Advanced age + poor ovarian reserve: discuss donor oocyte IVF as an alternative with significantly higher success rates.");
  }
  if (inputs.priorIVFAttempts >= 3 && !inputs.priorIVFSuccess) {
    warnings.push("3+ failed IVF cycles: consider PGT-A, immunologic evaluation, or donor oocyte discussion.");
  }
  if (inputs.stateMandate) {
    rationale.push("State infertility mandate applies: insurer is legally required to cover IVF per state law.");
  }

  return { recommendation, procedure, successRate, cor, loe, warnings, rationale, references };
}
